describe('User Login with Email or Username', () => {
  const baseUrl = 'http://localhost:3000';
  const testUser = {
    email: 'testuser@example.com',
    username: 'testuser123',
    password: 'SecurePassword123!'
  };

  beforeEach(() => {
    cy.visit(`${baseUrl}/login`);
    cy.get('[data-testid="login-form"]').should('be.visible');
  });

  it('should successfully log in using email address', () => {
    cy.get('[data-testid="login-input"]').type(testUser.email);
    cy.get('[data-testid="password-input"]').type(testUser.password);
    cy.get('[data-testid="login-button"]').click();

    cy.url().should('include', '/dashboard');
    cy.get('[data-testid="user-profile"]').should('be.visible');
    cy.get('[data-testid="user-name"]').should('contain', testUser.username);
  });

  it('should successfully log in using username', () => {
    cy.get('[data-testid="login-input"]').type(testUser.username);
    cy.get('[data-testid="password-input"]').type(testUser.password);
    cy.get('[data-testid="login-button"]').click();

    cy.url().should('include', '/dashboard');
    cy.get('[data-testid="user-profile"]').should('be.visible');
    cy.get('[data-testid="user-name"]').should('contain', testUser.username);
  });

  it('should display error message for invalid email credentials', () => {
    cy.get('[data-testid="login-input"]').type('invalid@example.com');
    cy.get('[data-testid="password-input"]').type('WrongPassword123!');
    cy.get('[data-testid="login-button"]').click();

    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Invalid credentials');
    cy.url().should('include', '/login');
  });

  it('should display error message for invalid username credentials', () => {
    cy.get('[data-testid="login-input"]').type('invaliduser');
    cy.get('[data-testid="password-input"]').type('WrongPassword123!');
    cy.get('[data-testid="login-button"]').click();

    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Invalid credentials');
    cy.url().should('include', '/login');
  });

  it('should display validation error when login input is empty', () => {
    cy.get('[data-testid="password-input"]').type(testUser.password);
    cy.get('[data-testid="login-button"]').click();

    cy.get('[data-testid="validation-error"]').should('be.visible');
    cy.get('[data-testid="validation-error"]').should('contain', 'Email or username is required');
  });

  it('should display validation error when password is empty', () => {
    cy.get('[data-testid="login-input"]').type(testUser.email);
    cy.get('[data-testid="login-button"]').click();

    cy.get('[data-testid="validation-error"]').should('be.visible');
    cy.get('[data-testid="validation-error"]').should('contain', 'Password is required');
  });

  it('should handle case-insensitive email login', () => {
    const uppercaseEmail = testUser.email.toUpperCase();
    cy.get('[data-testid="login-input"]').type(uppercaseEmail);
    cy.get('[data-testid="password-input"]').type(testUser.password);
    cy.get('[data-testid="login-button"]').click();

    cy.url().should('include', '/dashboard');
    cy.get('[data-testid="user-profile"]').should('be.visible');
  });

  it('should handle whitespace trimming in login input', () => {
    cy.get('[data-testid="login-input"]').type(`  ${testUser.username}  `);
    cy.get('[data-testid="password-input"]').type(testUser.password);
    cy.get('[data-testid="login-button"]').click();

    cy.url().should('include', '/dashboard');
    cy.get('[data-testid="user-profile"]').should('be.visible');
  });

  it('should clear error message when user corrects input', () => {
    cy.get('[data-testid="login-input"]').type('invalid@example.com');
    cy.get('[data-testid="password-input"]').type('WrongPassword123!');
    cy.get('[data-testid="login-button"]').click();

    cy.get('[data-testid="error-message"]').should('be.visible');

    cy.get('[data-testid="login-input"]').clear().type(testUser.email);
    cy.get('[data-testid="password-input"]').clear().type(testUser.password);
    cy.get('[data-testid="error-message"]').should('not.exist');
    cy.get('[data-testid="login-button"]').click();

    cy.url().should('include', '/dashboard');
  });
});
